import type {
  InferContractRouterInputs,
  InferContractRouterOutputs,
} from "@orpc/contract";
import { z } from "zod";
import { createContractProcedureBuilder } from "../errors";

const NUMERIC_UNITID_REGEX = /^\d+$/;
const IMAGE_CONTENT_TYPE_REGEX = /^image\//;

const IMAGE_ENTITY_TYPES = ["USER", "UNIVERSITY"] as const;
export const ImageEntityTypeSchema = z.enum(IMAGE_ENTITY_TYPES);
export type ImageEntityType = (typeof IMAGE_ENTITY_TYPES)[number];

const IMAGE_PROVIDER_VALUES = ["CLOUDFLARE_IMAGES"] as const;
export const ImageProviderSchema = z.enum(IMAGE_PROVIDER_VALUES);
export type ImageProvider = (typeof IMAGE_PROVIDER_VALUES)[number];

const IMAGE_TYPE_VALUES = [
  "LOGO",
  "BANNER",
  "CAMPUS_PHOTO",
  "PROFILE_PHOTO",
] as const;
export const ImageTypeSchema = z.enum(IMAGE_TYPE_VALUES);
export type ImageType = (typeof IMAGE_TYPE_VALUES)[number];

const entityReferenceSchema = z
  .object({
    entityType: ImageEntityTypeSchema,
    entityId: z.string().min(1, "Entity identifier is required"),
  })
  .strict()
  .superRefine((value, ctx) => {
    if (
      value.entityType === "UNIVERSITY" &&
      !NUMERIC_UNITID_REGEX.test(value.entityId)
    ) {
      ctx.addIssue({
        code: z.ZodIssueCode.custom,
        message: "University images must reference a numeric unitid",
        path: ["entityId"],
      });
    }
  });

const metadataSchema = z
  .record(z.string(), z.string())
  .refine((value) => Object.keys(value).length <= 20, {
    message: "Metadata cannot contain more than 20 keys",
  })
  .optional();

const imageVariantSchema = z
  .object({
    name: z.string().min(1),
    url: z.string().url(),
  })
  .strict();

const imageSchema = z
  .object({
    id: z.string(),
    entityType: ImageEntityTypeSchema,
    entityId: z.string(),
    sortOrder: z.number().int().nonnegative(),
    imageType: ImageTypeSchema.nullable(),
    isFeatured: z.boolean(),
    label: z.string().nullable(),
    altText: z.string().nullable(),
    caption: z.string().nullable(),
    metadata: z.record(z.string(), z.string()).nullable(),
    provider: ImageProviderSchema,
    providerImageId: z.string(),
    requireSignedUrls: z.boolean(),
    filename: z.string().nullable(),
    contentType: z.string().nullable(),
    fileSize: z.number().int().nonnegative().nullable(),
    width: z.number().int().positive().nullable(),
    height: z.number().int().positive().nullable(),
    checksum: z.string().nullable(),
    uploadedAt: z.string().nullable(),
    createdAt: z.string(),
    updatedAt: z.string(),
    originalStorageKey: z.string().nullable(),
    originalBucket: z.string().nullable(),
    originalChecksum: z.string().nullable(),
    originalFileSize: z.number().int().nonnegative().nullable(),
    defaultDeliveryUrl: z.string().url(),
    variants: z.array(imageVariantSchema),
  })
  .strict();

const listImagesInputSchema = entityReferenceSchema;

const listImagesOutputSchema = z
  .object({
    images: z.array(imageSchema),
  })
  .strict();

const createImageInputSchema = entityReferenceSchema
  .safeExtend({
    imageType: ImageTypeSchema.optional(),
    label: z.string().min(1).max(120).optional(),
    altText: z.string().min(1).max(180).optional(),
    caption: z.string().min(1).max(500).optional(),
    metadata: metadataSchema,
    requireSignedUrls: z.boolean().optional(),
    fileName: z.string().min(1).max(240),
    contentType: z
      .string()
      .regex(IMAGE_CONTENT_TYPE_REGEX, "Only image MIME types are supported"),
    fileBase64: z
      .string()
      .min(1, "Image payload is required")
      .max(21_000_000, "Image payload exceeds the 15MB limit"),
  })
  .strict();

const updateImageInputSchema = z
  .object({
    imageId: z.string().min(1),
    imageType: ImageTypeSchema.nullable().optional(),
    label: z.string().min(1).max(120).optional(),
    altText: z.string().min(1).max(180).optional(),
    caption: z.string().min(1).max(500).optional(),
    metadata: metadataSchema,
  })
  .strict()
  .refine((value) => {
    const { imageType, label, altText, caption, metadata } = value;
    return (
      imageType !== undefined ||
      label !== undefined ||
      altText !== undefined ||
      caption !== undefined ||
      metadata !== undefined
    );
  }, "At least one field must be provided for update");

const deleteImageInputSchema = z
  .object({
    imageId: z.string().min(1),
  })
  .strict();

const reorderImagesInputSchema = entityReferenceSchema
  .safeExtend({
    imageIds: z
      .array(z.string().min(1))
      .min(1, "At least one image is required for reordering")
      .max(100, "Cannot reorder more than 100 images at once"),
  })
  .strict();

const deleteImageOutputSchema = z
  .object({
    imageId: z.string(),
    deleted: z.literal(true),
  })
  .strict();

const replaceProfilePhotoInputSchema = z
  .object({
    entityType: z.literal("USER"),
    entityId: z.string().min(1, "User ID is required"),
    label: z.string().min(1).max(120).optional(),
    altText: z.string().min(1).max(180).optional(),
    caption: z.string().min(1).max(500).optional(),
    metadata: metadataSchema,
    requireSignedUrls: z.boolean().optional(),
    fileName: z.string().min(1).max(240),
    contentType: z
      .string()
      .regex(IMAGE_CONTENT_TYPE_REGEX, "Only image MIME types are supported"),
    fileBase64: z
      .string()
      .min(1, "Image payload is required")
      .max(21_000_000, "Image payload exceeds the 15MB limit"),
  })
  .strict();

const setFeaturedImageInputSchema = z
  .object({
    imageId: z.string().min(1),
  })
  .strict();

const contractProcedure = createContractProcedureBuilder();

export const imagesContract = {
  list: contractProcedure
    .input(listImagesInputSchema)
    .output(listImagesOutputSchema),
  create: contractProcedure.input(createImageInputSchema).output(imageSchema),
  update: contractProcedure.input(updateImageInputSchema).output(imageSchema),
  delete: contractProcedure
    .input(deleteImageInputSchema)
    .output(deleteImageOutputSchema),
  reorder: contractProcedure
    .input(reorderImagesInputSchema)
    .output(listImagesOutputSchema),
  replaceProfilePhoto: contractProcedure
    .input(replaceProfilePhotoInputSchema)
    .output(imageSchema),
  setFeaturedImage: contractProcedure
    .input(setFeaturedImageInputSchema)
    .output(imageSchema),
};

export type ImagesContract = typeof imagesContract;
export type ImagesContractInputs = InferContractRouterInputs<ImagesContract>;
export type ImagesContractOutputs = InferContractRouterOutputs<ImagesContract>;

export type ListImagesInput = ImagesContractInputs["list"];
export type ListImagesOutput = ImagesContractOutputs["list"];
export type CreateImageInput = ImagesContractInputs["create"];
export type CreateImageOutput = ImagesContractOutputs["create"];
export type UpdateImageInput = ImagesContractInputs["update"];
export type UpdateImageOutput = ImagesContractOutputs["update"];
export type DeleteImageInput = ImagesContractInputs["delete"];
export type DeleteImageOutput = ImagesContractOutputs["delete"];
export type ReorderImagesInput = ImagesContractInputs["reorder"];
export type ReorderImagesOutput = ImagesContractOutputs["reorder"];
export type ReplaceProfilePhotoInput =
  ImagesContractInputs["replaceProfilePhoto"];
export type ReplaceProfilePhotoOutput =
  ImagesContractOutputs["replaceProfilePhoto"];
export type SetFeaturedImageInput = ImagesContractInputs["setFeaturedImage"];
export type SetFeaturedImageOutput = ImagesContractOutputs["setFeaturedImage"];
